package seed

import (
	"github.com/xdanny/hyperplane-workflows/internal/sdkworkflow"
	"github.com/xdanny/hyperplane-workflows/internal/store"
)

func pipelineChangeTemplate() store.WorkflowTemplate {
	return sdkNodeTemplate("pipeline-change", "Capture the real baseline, approve an exact change plan, and deliver a checked pipeline change with regression and rollback evidence.", "Change the declared pipeline in local deliverable copies, preserving the original.\nThe pipeline you are changing: {slot:pipelineLocation}\nHow the existing pipeline runs: {slot:runCommand}\nWhat must change, and why: {slot:changeRequest}\nWhat must NOT change: {slot:invariants}\nGrain: {slot:grain}\nKey columns: {slot:keyColumns}\nWhat is confidential here, and what these numbers must not be used for: {slot:safeUse}\nRuntime budget: {slot:runtimeBudget}\nBlank optional context is unspecified. Review and configure source access and temporary tools per step; no external writes or publishing are authorized by this recipe.", []store.ContextSlot{{ID: "pipelineLocation", Label: "The pipeline you are changing", Hint: "The existing code, model manifest, declared input data and delivery convention. Use absolute local paths or named source references; never credentials.", Required: true, Example: "/data/pipeline/pipeline.py; reads /data/orders.csv; reviewed changes delivered as files", Audience: store.SlotAudienceEngineer},
		{ID: "runCommand", Label: "How the existing pipeline runs", Hint: "The exact existing end-to-end command. The SDK runs it on a local copy and captures its outputs before planning changes.", Required: true, Example: "python3 pipeline.py", Audience: store.SlotAudienceEngineer},
		{ID: "changeRequest", Label: "What must change, and why", Hint: "The behavior that is wrong or missing today, and what must be true afterwards.", Required: true, Example: "Convert EU refunds at the refund-date rate before subtracting them."},
		{ID: "invariants", Label: "What must NOT change", Hint: "Every protected number or behavior with its own kind and tolerance. Exact equality uses zero; percentages use the absolute baseline value.", Required: true, Example: "[{\"invariant\":\"US revenue\",\"measure\":\"us_net\",\"kind\":\"number\",\"unit\":\"absolute\",\"tolerance\":\"0.01\"}]", Type: store.SlotTypeTable, Columns: []store.SlotColumn{{ID: "invariant", Label: "What must stay true", Required: true}, {ID: "measure", Label: "Measure or behavior", Required: true}, {ID: "kind", Label: "Value type", Required: true, Options: []string{"number", "boolean", "text"}}, {ID: "unit", Label: "Tolerance unit", Required: true, Options: []string{"absolute", "count", "exact", "percent_of_baseline"}}, {ID: "tolerance", Label: "Tolerance", Required: false}}},
		{ID: "grain", Label: "Grain", Hint: "What one row of the affected model represents. Declare the identifying columns separately in Key columns.", Required: true, Example: "one row per order id", Audience: store.SlotAudienceEngineer},
		{ID: "keyColumns", Label: "Key columns", Hint: "Comma-separated columns identifying a row; use none followed by candidates if there is no natural key. Report whether they hold.", Required: true, Example: "id", Audience: store.SlotAudienceEngineer, Type: store.SlotTypeList},
		{ID: "safeUse", Label: "What is confidential here, and what these numbers must not be used for", Hint: "Sensitive fields to exclude and limits on downstream decisions. Deliver only the allowed models, with staging kept separate.", Required: true, Example: "Customer email must not appear in delivered models; internal reporting only."},
		{ID: "runtimeBudget", Label: "Runtime budget", Hint: "Optional duration for baseline and regression checks. Generated checks enforce it; the application also applies its own total run deadline.", Required: false, Example: "Each capture and regression inside 25 minutes."}}, []sdkworkflow.Node{{ID: "profile", Kind: "task", Title: "Capture the existing pipeline", Instruction: "Capture only the original pipeline baseline against declared data. Preserve original sources, all protected invariants and the requested grain. Follow the built-in baseline output and execution contract supplied by the SDK extension; do not implement the future change.", Acceptance: "pipeline-change-profile", Inputs: map[string]string{"pipelineLocation": "{slot:pipelineLocation}", "runCommand": "{slot:runCommand}", "changeRequest": "{slot:changeRequest}", "invariants": "{slot:invariants}", "grain": "{slot:grain}", "keyColumns": "{slot:keyColumns}", "safeUse": "{slot:safeUse}"}},
		{ID: "baseline-review", Kind: "check", Title: "Review the measured baseline", Instruction: "Independently inspect the actual files and programs, not only the model handoff. Judge the declared context and required behavior. Report a failure for missing, contradicted or invented evidence. State the controlling finding clearly, with file references; preserve uncertainty and distinguish program execution from semantic correctness. Verify the declared command ran on a faithful read-only copy against the real sources; output snapshots, row/date bounds and every invariant are measured. Check declared tolerance ownership, the independent parse path, source snapshot identity and actual candidate-key counts. A baseline that cannot execute or an unmeasurable protected invariant fails. Name consumer discovery limits."},
		{ID: "rules", Kind: "task", Title: "Plan the pipeline change", Instruction: "Plan the requested change from the measured baseline. Preserve the owner invariants and tolerances. Map affected columns and consumers, executable steps, rollback, the new behavior that the baseline lacks, and the copied-data negative change with its expected set of failing invariant names. Follow the built-in plan output contract; do not implement before approval.", Acceptance: "pipeline-change-rules"},
		{ID: "plan-review", Kind: "check", Title: "Review impact and rollback", Instruction: "Independently inspect the actual files and programs, not only the model handoff. Judge the declared context and required behavior. Report a failure for missing, contradicted or invented evidence. State the controlling finding clearly, with file references; preserve uncertainty and distinguish program execution from semantic correctness. Every invariant must preserve its original name, measure, kind, baseline and owner tolerance. Verify the impact map follows changed columns to readers, migration steps can execute, rollback refers to preserved files and has a realistic safe window, and the new-behavior assertion can fail on the captured baseline. Reject conflict with protected behavior or confidentiality; do not invent extra requirements."},
		{ID: "approve-change", Kind: "approval", Title: "Approve the change and rollback", Instruction: "Review baseline-report.json and change-plan.json. Confirm the requested behavior, protected invariants and their exact tolerances, downstream impact, local deliverables, rollback, the copied-data negative change and its exact expected failing invariant set, and safe-use limits before implementation."},
		{ID: "audit", Kind: "task", Title: "Implement and prove the change", Instruction: "Implement the approved pipeline change as local deliverable copies. Execute regression on the same original data snapshot, prove the requested behavior false before and true after, and verify that the copied negative case fails exactly the approved invariant set. Preserve confidentiality, every invariant and the approved migration/rollback. Follow the built-in implementation and regression output contract; do not deploy or modify original sources.", Acceptance: "pipeline-change-audit"},
		{ID: "regression-review", Kind: "check", Title: "Review execution and regression", Instruction: "Independently inspect the actual files and programs, not only the model handoff. Judge the declared context and required behavior. Report a failure for missing, contradicted or invented evidence. State the controlling finding clearly, with file references; preserve uncertainty and distinguish program execution from semantic correctness. Verify every protected invariant was executed on the real changed pipeline with expected values from the actual captured baseline and exact owner tolerances. Recalculate deltas/verdicts. Check the same approved behavior assertion fails on baseline output and passes after the change, and the same regression programs reject exactly the approved set of invariants in the copied-data negative case, with no missing or additional failures. Coupled measures may fail together; the plan must name that set before approval. Inspect actual program/source paths, snapshot identity, independent parse, grain, output publication boundary, confidentiality and any declared timing budget. Reject fixture substitution, hardcoded results, source drift, no-op changes and missing checks."},
		{ID: "owner-review", Kind: "check", Title: "Review the effect on dependent reports", Instruction: "Independently inspect the actual files and programs, not only the model handoff. Judge the declared context and required behavior. Report a failure for missing, contradicted or invented evidence. State the controlling finding clearly, with file references; preserve uncertainty and distinguish program execution from semantic correctness. Confirm the delivered code implements the approved request, the protected contract still holds, affected consumers are accounted for, staging and confidential fields do not leak into delivered models, and rollback remains possible. State what cannot be established; never describe a local deliverable as deployed."},
		{ID: "summary", Kind: "document", Title: "Explain the change and evidence", Instruction: "Return standalone Markdown. Lead with what changed and what the owner should do next. Explain what did not change using each measured baseline, observed value, exact delta, tolerance and unit. Show false-before/true-after evidence for the requested behavior, the approved negative change, its expected and observed failing invariants, affected consumers, rollback instructions and their safe window, confidentiality and publication limits. Link actual delivered files and reports. Preserve all uncertainty and blocked consumer checks; do not claim deployment, publication or general correctness beyond the executed evidence. Define technical terms and every count denominator for a first-time reader."},
		{ID: "summary-review", Kind: "check", Title: "Review the handover", Instruction: "Independently inspect the actual files and programs, not only the model handoff. Judge the declared context and required behavior. Report a failure for missing, contradicted or invented evidence. State the controlling finding clearly, with file references; preserve uncertainty and distinguish program execution from semantic correctness. The summary must match the actual regression and files, state the change and next action early, explain each invariant with its baseline/delta/tolerance, preserve unresolved risks, show rollback and distinguish local artifacts from deployment. A reassuring claim that contradicts a failed or missing check fails."}}...)
}
